answer:
**考点**：单例 + 线程安全 + C++11 静态局部变量特性。

**推荐写法（C++11 静态局部变量，最简洁且线程安全）**：

```cpp
class Singleton {
public:
    static Singleton& getInstance() {
        static Singleton instance;   // C++11 保证局部静态变量初始化线程安全
        return instance;
    }
    Singleton(const Singleton&) = delete;            // 禁止拷贝
    Singleton& operator=(const Singleton&) = delete; // 禁止赋值
private:
    Singleton() = default;   // 构造私有，外部无法 new
    ~Singleton() = default;
};
```

**双重检查锁写法（旧式，讲原理时用）**：

```cpp
class Singleton {
public:
    static Singleton* getInstance() {
        if (instance_ == nullptr) {              // 第一层检查，避免每次加锁
            std::lock_guard<std::mutex> lock(mtx_);
            if (instance_ == nullptr) {          // 第二层检查，防止重复创建
                instance_ = new Singleton();
            }
        }
        return instance_;
    }
private:
    Singleton() = default;
    static Singleton* instance_;
    static std::mutex mtx_;
};
Singleton* Singleton::instance_ = nullptr;
std::mutex Singleton::mtx_;
```

**边界坑点**：
- 双重检查锁里**两次判空缺一不可**：第一层是性能优化（避免每次加锁），第二层是正确性（防止多个线程都过了第一层判断后重复 new）。
- 旧式双重检查锁在 C++11 前有**内存序问题**（new 的"分配内存/构造/赋值"可能重排），需要 volatile 或内存屏障；**C++11 之后静态局部变量写法最安全，优先用它**。
- 别忘了**禁止拷贝构造和赋值**，否则 `Singleton s = getInstance()` 会复制出新实例，破坏单例。

**考点**：引用计数、控制块思想、RAII、拷贝/移动语义。

```cpp
template<typename T>
class SharedPtr {
private:
    T* ptr_;          // 指向对象
    size_t* count_;   // 引用计数（独立堆分配，多个 shared_ptr 共享）
public:
    explicit SharedPtr(T* p = nullptr) : ptr_(p), count_(new size_t(1)) {}

    // 拷贝构造：共享同一计数，计数 +1
    SharedPtr(const SharedPtr& other) : ptr_(other.ptr_), count_(other.count_) {
        ++(*count_);
    }

    // 移动构造：接管资源，源置空
    SharedPtr(SharedPtr&& other) noexcept : ptr_(other.ptr_), count_(other.count_) {
        other.ptr_ = nullptr;
        other.count_ = nullptr;
    }

    SharedPtr& operator=(const SharedPtr& other) {
        if (this != &other) {          // 处理自赋值
            release();                 // 先释放自己当前持有的
            ptr_ = other.ptr_;
            count_ = other.count_;
            ++(*count_);
        }
        return *this;
    }

    ~SharedPtr() { release(); }

    T& operator*() const { return *ptr_; }
    T* operator->() const { return ptr_; }
    T* get() const { return ptr_; }
    size_t use_count() const { return *count_; }

private:
    void release() {
        if (--(*count_) == 0) {        // 计数归零才真正释放
            delete ptr_;
            delete count_;
        }
    }
};
```

**边界坑点**：
- **赋值运算符要处理自赋值**（`a = a`）：不判断的话，先 release 把自己删了，再去读 other 的 count 就悬空了。
- **计数和对象分开堆分配**：因为多个 shared_ptr 要共享同一个计数，计数必须是独立的堆对象（这正是真实 shared_ptr 里"控制块"的作用）。
- 真实 shared_ptr 还涉及**弱引用计数、自定义删除器、线程安全（原子计数）**，面试说出来是加分项，但手写实现能到这个程度已经足够。

**考点**：独占所有权、移动语义、禁止拷贝。

```cpp
template<typename T>
class UniquePtr {
private:
    T* ptr_;
public:
    explicit UniquePtr(T* p = nullptr) : ptr_(p) {}
    ~UniquePtr() { delete ptr_; }

    UniquePtr(const UniquePtr&) = delete;             // 禁止拷贝
    UniquePtr& operator=(const UniquePtr&) = delete;

    UniquePtr(UniquePtr&& other) noexcept : ptr_(other.ptr_) {   // 移动构造
        other.ptr_ = nullptr;
    }
    UniquePtr& operator=(UniquePtr&& other) noexcept {            // 移动赋值
        if (this != &other) {
            delete ptr_;             // 先释放自己的
            ptr_ = other.ptr_;
            other.ptr_ = nullptr;
        }
        return *this;
    }

    T& operator*() const { return *ptr_; }
    T* operator->() const { return ptr_; }
    T* get() const { return ptr_; }
    T* release() {                 // 放弃所有权，返回裸指针
        T* tmp = ptr_;
        ptr_ = nullptr;
        return tmp;
    }
};
```

**边界坑点**：
- **移动赋值要处理自移动**（`a = std::move(a)`），否则先 delete 自己再读 other（就是自己）的指针就出问题。
- 移动后**源指针必须置空**，否则两个 unique_ptr 指向同一对象，析构时 double free。
- `release()` 返回裸指针并置空自己，调用者拿到后要自己负责释放——这是把所有权"交出去"。

**考点**：动态扩容、均摊复杂度、深拷贝、移动语义。

```cpp
template<typename T>
class MyVector {
private:
    T* data_;
    size_t size_;
    size_t capacity_;
public:
    MyVector() : data_(nullptr), size_(0), capacity_(0) {}
    ~MyVector() { delete[] data_; }

    void push_back(const T& val) {
        if (size_ == capacity_) {
            size_t new_cap = (capacity_ == 0) ? 1 : capacity_ * 2;  // 翻倍扩容
            reserve(new_cap);
        }
        data_[size_++] = val;
    }

    void reserve(size_t new_cap) {
        if (new_cap <= capacity_) return;
        T* new_data = new T[new_cap];
        for (size_t i = 0; i < size_; ++i) {
            new_data[i] = std::move(data_[i]);   // 用移动，避免深拷贝
        }
        delete[] data_;
        data_ = new_data;
        capacity_ = new_cap;
    }

    T& operator[](size_t i) { return data_[i]; }
    const T& operator[](size_t i) const { return data_[i]; }
    size_t size() const { return size_; }
    size_t capacity() const { return capacity_; }
};
```

**边界坑点**：
- **扩容是翻倍（×2）而不是加固定值**：这样均摊每次 push_back 是 O(1)；加固定值会退化。
- reserve 里搬移元素用 `std::move`（移动），对含堆资源的对象避免深拷贝；但前提是 T 有**移动构造且 noexcept**（真实 vector 会判断）。
- `capacity_ == 0` 时 `×2` 还是 0，所以要特殊处理成 1。
- 真实 vector 的 push_back 还有 emplace_back（原地构造）、迭代器失效等问题，面试可以带一句。

**考点**：分治 + partition、复杂度、最坏情况。

```cpp
// 划分：返回 pivot 最终位置
int partition(std::vector<int>& arr, int left, int right) {
    int pivot = arr[left];           // 以最左元素为基准
    int i = left, j = right;
    while (i < j) {
        while (i < j && arr[j] >= pivot) --j;   // 从右找比 pivot 小的
        while (i < j && arr[i] <= pivot) ++i;   // 从左找比 pivot 大的
        if (i < j) std::swap(arr[i], arr[j]);
    }
    arr[left] = arr[i];              // pivot 归位
    arr[i] = pivot;
    return i;
}

void quickSort(std::vector<int>& arr, int left, int right) {
    if (left >= right) return;
    int p = partition(arr, left, right);
    quickSort(arr, left, p - 1);
    quickSort(arr, p + 1, right);
}
```

**边界坑点**：
- **内层两个 while 里必须带 `i < j` 判断**，否则会越界或死循环。
- 内层**先 j 后 i 的顺序**不能反（先动右边的指针），否则最终 i 停的位置可能比 pivot 大，交换后破坏有序。
- **最坏 O(n²)**：数组已经有序（每次划分极不平衡）。优化：**三数取中选 pivot**、**小数组改插入排序**、随机 pivot。
- 手写时最容易错的就是 partition 的边界，建议把上面这套模板背熟。

**考点**：分治 + 合并两个有序数组、稳定排序、O(n) 空间。

```cpp
void merge(std::vector<int>& arr, int left, int mid, int right) {
    std::vector<int> tmp(right - left + 1);
    int i = left, j = mid + 1, k = 0;
    while (i <= mid && j <= right) {
        tmp[k++] = (arr[i] <= arr[j]) ? arr[i++] : arr[j++];  // <= 保证稳定
    }
    while (i <= mid)  tmp[k++] = arr[i++];
    while (j <= right) tmp[k++] = arr[j++];
    for (int p = 0; p < k; ++p) arr[left + p] = tmp[p];
}

void mergeSort(std::vector<int>& arr, int left, int right) {
    if (left >= right) return;
    int mid = left + (right - left) / 2;   // 防溢出写法
    mergeSort(arr, left, mid);
    mergeSort(arr, mid + 1, right);
    merge(arr, left, mid, right);
}
```

**边界坑点**：
- `mid = left + (right - left) / 2` 而不是 `(left + right) / 2`，**防止 left+right 溢出**。
- merge 里 `arr[i] <= arr[j]` 用 `<=` 是**保证稳定性**的关键（相等时先取左边）。
- 空间 O(n)（tmp 数组），时间复杂度**稳定 O(n log n)**，这是和快排的区别。

**考点**：大顶堆、heapify（下沉）、建堆。

```cpp
// 下沉：把 i 调整为以它为根的大顶堆
void heapify(std::vector<int>& arr, int n, int i) {
    int largest = i;
    int left = 2 * i + 1, right = 2 * i + 2;
    if (left  < n && arr[left]  > arr[largest]) largest = left;
    if (right < n && arr[right] > arr[largest]) largest = right;
    if (largest != i) {
        std::swap(arr[i], arr[largest]);
        heapify(arr, n, largest);   // 递归下沉
    }
}

void heapSort(std::vector<int>& arr) {
    int n = arr.size();
    for (int i = n / 2 - 1; i >= 0; --i) heapify(arr, n, i);  // 建堆：从最后非叶子开始
    for (int i = n - 1; i > 0; --i) {
        std::swap(arr[0], arr[i]);   // 堆顶（最大）移到末尾
        heapify(arr, i, 0);          // 调整剩余部分
    }
}
```

**边界坑点**：
- **建堆从 `n/2 - 1`（最后一个非叶子节点）开始往前**，不是从 0 开始。
- 数组下标关系：i 的左孩子 `2i+1`、右孩子 `2i+2`、父 `(i-1)/2`。
- 堆排序**不稳定**，空间 O(1)，复杂度 O(n log n)。
- 优先队列（priority_queue）底层就是这个。

**考点**：有序数组查找、边界条件、lower_bound/upper_bound。

```cpp
// 基础版：找 target 下标，找不到返回 -1
int binarySearch(std::vector<int>& arr, int target) {
    int left = 0, right = arr.size() - 1;   // 左闭右闭
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (arr[mid] == target) return mid;
        else if (arr[mid] < target) left = mid + 1;
        else right = mid - 1;
    }
    return -1;
}

// 变种：第一个 >= target 的位置（即 lower_bound）
int lowerBound(std::vector<int>& arr, int target) {
    int left = 0, right = arr.size();       // 左闭右开
    while (left < right) {
        int mid = left + (right - left) / 2;
        if (arr[mid] < target) left = mid + 1;
        else right = mid;                   // 收紧右边界
    }
    return left;
}

// 变种：第一个 > target 的位置（即 upper_bound）
int upperBound(std::vector<int>& arr, int target) {
    int left = 0, right = arr.size();
    while (left < right) {
        int mid = left + (right - left) / 2;
        if (arr[mid] <= target) left = mid + 1;
        else right = mid;
    }
    return left;
}
```

**边界坑点**：
- **两套模板别混用**：基础版是"左闭右闭 + `left <= right`"，lower/upper 是"左闭右开 + `left < right`"，混用必错。
- `mid = left + (right - left) / 2` 防溢出。
- 关键记法：**lower_bound 是"找第一个满足 `arr[mid] >= target` 的"**，upper_bound 是"第一个满足 `arr[mid] > target` 的"。
- 变种还有"旋转数组找最小/找目标"，但二分核心都是"每次排除一半"。

**考点**：指针操作、迭代 + 递归。

```cpp
struct ListNode {
    int val;
    ListNode* next;
    ListNode(int x) : val(x), next(nullptr) {}
};

// 迭代版（面试首选，不会爆栈）
ListNode* reverseList(ListNode* head) {
    ListNode* prev = nullptr;
    ListNode* curr = head;
    while (curr) {
        ListNode* next = curr->next;  // 先保存下一个，防止断链
        curr->next = prev;            // 反转指向
        prev = curr;
        curr = next;
    }
    return prev;                       // prev 是新头
}

// 递归版
ListNode* reverseListRec(ListNode* head) {
    if (!head || !head->next) return head;   // 递归到最后一个节点
    ListNode* newHead = reverseListRec(head->next);
    head->next->next = head;                 // 让后一个节点指向自己
    head->next = nullptr;                    // 断开原来的指向
    return newHead;
}
```

**边界坑点**：
- 迭代版**必须先保存 next 再改 curr->next**，否则断链就找不到后面的节点了。
- 递归版最后要 `head->next = nullptr`，否则链尾会成环。
- 空链表、单节点链表都要能正确处理（`!head` 判断）。

**考点**：快慢指针（Floyd 判圈）。

```cpp
// 判断是否有环
bool hasCycle(ListNode* head) {
    ListNode* slow = head, *fast = head;
    while (fast && fast->next) {        // fast 走两步，所以要判断 fast->next
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) return true;  // 相遇说明有环
    }
    return false;
}

// 找环的入口
ListNode* detectCycle(ListNode* head) {
    ListNode* slow = head, *fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) {             // 相遇后
            ListNode* p = head;
            while (p != slow) {         // 一个从头走、一个从相遇点走
                p = p->next;
                slow = slow->next;
            }
            return p;                    // 再次相遇点就是环入口
        }
    }
    return nullptr;
}
```

**边界坑点**：
- **while 条件是 `fast && fast->next`**（因为 fast 要跳两步，得保证 fast->next 存在）。
- 找入口的数学原理：从头到环入口 = 从相遇点到环入口，所以一个从头走、一个从相遇点走，再次相遇就是入口。
- 空链表、无环要正确返回。

**考点**：哈希表 + 双向链表，get/put O(1)。

```cpp
class LRUCache {
private:
    int cap_;
    std::list<std::pair<int,int>> cache_;          // 双向链表，头=最近，尾=最久
    std::unordered_map<int, std::list<std::pair<int,int>>::iterator> mp_;
public:
    LRUCache(int capacity) : cap_(capacity) {}

    int get(int key) {
        auto it = mp_.find(key);
        if (it == mp_.end()) return -1;
        cache_.splice(cache_.begin(), cache_, it->second);  // 移到链表头
        return it->second->second;
    }

    void put(int key, int value) {
        auto it = mp_.find(key);
        if (it != mp_.end()) {                      // key 已存在
            it->second->second = value;
            cache_.splice(cache_.begin(), cache_, it->second);
            return;
        }
        if (cache_.size() == cap_) {                // 满了，删最久未用（尾部）
            mp_.erase(cache_.back().first);
            cache_.pop_back();
        }
        cache_.push_front({key, value});
        mp_[key] = cache_.begin();
    }
};
```

**边界坑点**：
- **为什么用双向链表**：删除任意节点（尾部的）要 O(1)，单链表做不到；`splice` 是 list 特有的 O(1) 移动。
- **哈希表存的是"链表迭代器"**（不是 value），这样才能 O(1) 定位到链表节点去移动/删除。
- 用 `std::list` + `unordered_map` 是标准写法；如果要求**手写双向链表**（不用 STL），要自己实现节点的 add/remove，原理一样。

**考点**：栈 LIFO → 队列 FIFO 的转换。

```cpp
class MyQueue {
private:
    std::stack<int> in_, out_;
    void move() {                 // 只有 out 空时才把 in 全部倒过来
        if (out_.empty()) {
            while (!in_.empty()) {
                out_.push(in_.top());
                in_.pop();
            }
        }
    }
public:
    void push(int x) { in_.push(x); }
    int pop() {
        move();
        int v = out_.top(); out_.pop();
        return v;
    }
    int peek() {
        move();
        return out_.top();
    }
    bool empty() { return in_.empty() && out_.empty(); }
};
```

**边界坑点**：
- **move() 只在 out_ 为空时才倒**，否则会破坏顺序（新 push 的会把老元素压到下面）。
- 均摊复杂度：每个元素最多"入 in、出 in、入 out、出 out"各一次，均摊 O(1)。
- 两个队列实现栈：入栈时把新元素入队，然后把前面所有元素依次出队再入队，让新元素在队首。

**考点**：互斥锁 + 两个条件变量、虚假唤醒。

```cpp
class BoundedQueue {
private:
    std::queue<int> q_;
    std::mutex mtx_;
    std::condition_variable not_full_, not_empty_;
    int cap_;
public:
    BoundedQueue(int cap) : cap_(cap) {}

    void produce(int x) {
        std::unique_lock<std::mutex> lock(mtx_);
        not_full_.wait(lock, [this]{ return q_.size() < cap_; });  // 不满才生产
        q_.push(x);
        not_empty_.notify_one();   // 通知消费者
    }

    int consume() {
        std::unique_lock<std::mutex> lock(mtx_);
        not_empty_.wait(lock, [this]{ return !q_.empty(); });      // 不空才消费
        int v = q_.front(); q_.pop();
        not_full_.notify_one();    // 通知生产者
        return v;
    }
};
```

**边界坑点**：
- **wait 必须用带谓词的版本**（`wait(lock, 条件)`），内部是 `while(!条件) wait`，防止**虚假唤醒**。
- **两个条件变量**：生产者等"不满"、消费者等"不空"，各等各的，避免互相误唤醒。
- 必须用 `unique_lock`（不能 lock_guard），因为条件变量 wait 需要"解锁-等待-再加锁"的能力。
- 有界队列（cap 限制）能自然**削峰限流**，这也是它和普通队列的区别。

**考点**：小顶堆维护最大 K 个。

```cpp
std::vector<int> topK(std::vector<int>& nums, int k) {
    std::priority_queue<int, std::vector<int>, std::greater<int>> minHeap;  // 小顶堆
    for (int x : nums) {
        if (minHeap.size() < k) {
            minHeap.push(x);
        } else if (x > minHeap.top()) {   // 比堆顶大才替换
            minHeap.pop();
            minHeap.push(x);
        }
    }
    std::vector<int> res;
    while (!minHeap.empty()) {
        res.push_back(minHeap.top());
        minHeap.pop();
    }
    return res;
}
```

**边界坑点**：
- **求最大 K 个用小顶堆**（堆顶是 K 个里最小的，来了更大的就替换），别搞反。
- `priority_queue<int, vector<int>, greater<int>>` 是小顶堆（greater 得到小顶堆，容易记反）。
- 复杂度 O(n log K)，空间 O(K)，是海量数据 TopK 的标准做法。

**考点**：滑动窗口 + 哈希表。

```cpp
int lengthOfLongestSubstring(std::string s) {
    std::unordered_map<char, int> pos;   // 字符 → 最近出现位置
    int left = 0, maxLen = 0;
    for (int right = 0; right < (int)s.size(); ++right) {
        if (pos.count(s[right])) {
            left = std::max(left, pos[s[right]] + 1);  // 收缩左边界
        }
        pos[s[right]] = right;
        maxLen = std::max(maxLen, right - left + 1);
    }
    return maxLen;
}
```

**边界坑点**：
- **left 要用 `max(left, pos+1)` 而不是直接 `pos+1`**，否则左边界可能回退（重复字符在窗口外时）。
- 滑动窗口模板：右指针扩展、左指针按条件收缩、在过程中更新最优解。

**考点**：字符串处理、边界、溢出。

```cpp
int myAtoi(std::string s) {
    int i = 0, n = s.size();
    while (i < n && s[i] == ' ') ++i;          // 跳过前导空格
    int sign = 1;
    if (i < n && (s[i] == '+' || s[i] == '-')) {
        sign = (s[i] == '-') ? -1 : 1;
        ++i;
    }
    long long result = 0;
    while (i < n && std::isdigit(s[i])) {
        result = result * 10 + (s[i] - '0');
        if (result * sign > INT_MAX) return INT_MAX;   // 溢出处理
        if (result * sign < INT_MIN) return INT_MIN;
        ++i;
    }
    return (int)(result * sign);
}
```

**边界坑点**：
- **溢出**：用 long long 存中间结果，每次迭代判断是否超 INT_MAX/INT_MIN，超了就返回边界值（这是标准要求）。
- 处理顺序：**空格 → 符号 → 数字**，遇到非数字就停。
- 空字符串、只有符号、前导零都要正确。

**考点**：栈模拟递归、队列做层序。

```cpp
struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

// 前序：根左右（栈，先压右再压左）
std::vector<int> preorder(TreeNode* root) {
    std::vector<int> res;
    std::stack<TreeNode*> st;
    if (root) st.push(root);
    while (!st.empty()) {
        TreeNode* node = st.top(); st.pop();
        res.push_back(node->val);
        if (node->right) st.push(node->right);   // 先右后左
        if (node->left)  st.push(node->left);
    }
    return res;
}

// 中序：左根右（一直往左走，弹栈访问，转右）
std::vector<int> inorder(TreeNode* root) {
    std::vector<int> res;
    std::stack<TreeNode*> st;
    TreeNode* cur = root;
    while (cur || !st.empty()) {
        while (cur) {                // 一直往左压栈
            st.push(cur);
            cur = cur->left;
        }
        cur = st.top(); st.pop();
        res.push_back(cur->val);
        cur = cur->right;            // 转向右子树
    }
    return res;
}

// 层序：队列，按层
std::vector<std::vector<int>> levelOrder(TreeNode* root) {
    std::vector<std::vector<int>> res;
    if (!root) return res;
    std::queue<TreeNode*> q;
    q.push(root);
    while (!q.empty()) {
        int size = q.size();         // 当前层节点数
        std::vector<int> level;
        for (int i = 0; i < size; ++i) {
            TreeNode* node = q.front(); q.pop();
            level.push_back(node->val);
            if (node->left)  q.push(node->left);
            if (node->right) q.push(node->right);
        }
        res.push_back(level);
    }
    return res;
}
```

**边界坑点**：
- **前序非递归：先压右孩子再压左孩子**（栈是后进先出，先弹左）。
- **中序非递归**：`while (cur || !st.empty())` 这个循环条件很关键，两个条件缺一不可。
- **层序要记录 size**（当前层节点数），才能按层输出。

